#include <iostream>
using namespace std;

void pour() noexcept {
    cout << "倒{word}" << endl;
}

void shake() {
    cout << "摇一摇" << endl;
}

int main() {
    pour();
    shake();
    cout << "pour 那张票：" << noexcept(pour()) << endl;
    cout << "shake 那张票：" << noexcept(shake()) << endl;
    return 0;
}
